<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api } from '@/api';
const loading=ref(false); const rows=ref<any[]>([]); const load=async()=>{loading.value=true;try{const result=await api.get('/audit-logs/');rows.value=result.results||result}finally{loading.value=false}}; onMounted(load);
</script>
<template><div class="page" v-loading="loading"><header class="page-header"><div><h1>管理审计日志</h1><p>记录员工、操作原因、资源、请求 ID 和前后状态摘要。</p></div><el-button @click="load">刷新</el-button></header><div class="data-surface" style="margin-top:18px"><el-table :data="rows"><el-table-column label="员工" min-width="180"><template #default="{row}">{{row.actor?.email||'系统'}}</template></el-table-column><el-table-column prop="action" label="动作" min-width="150" /><el-table-column prop="resource_type" label="资源" min-width="140" /><el-table-column prop="resource_id" label="资源 ID" min-width="170" show-overflow-tooltip /><el-table-column prop="operation_reason" label="操作原因" min-width="240" show-overflow-tooltip /><el-table-column prop="request_id" label="Request ID" min-width="180" show-overflow-tooltip /><el-table-column prop="created_at" label="时间" min-width="180" /></el-table></div></div></template>
